      border-radius: 50%;
    }

    .header::after {
      content: '';
      position: absolute;
      bottom: -60px;
      right: -60px;
      width: 150px;
      height: 150px;
      background: rgba(255, 255, 255, 0.1);
      border-radius: 50%;
    }

    .header h1 {
      font-size: 1.4rem;
      font-weight: 700;
      margin-bottom: 8px;
      position: relative;
      z-index: 2;
    }

    .header p {
      font-size: 0.9rem;
      opacity: 0.9;
      line-height: 1.4;
      position: relative;
      z-index: 2;
    }

    .header-icon {
      font-size: 48px;
      margin-bottom: 10px;
      display: inline-block;
      animation: bounce 2s ease infinite;
    }

    @keyframes bounce {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-10px); }
    }

    /* 版本对比 */
    .version-comparison {
      display: flex;
      flex-wrap: nowrap;
      gap: 12px;
      padding: 16px;
      margin-top: 8px;
      position: relative;
      z-index: 10;
    }

    .version-card {
      flex: 1;
      min-width: 45%;
      background: var(--card-bg);
      border-radius: 16px;
      padding: 28px 16px 16px;
      box-shadow: var(--shadow);
      text-align: center;
      position: relative;
      transition: transform 0.3s ease, box-shadow 0.3s ease;
      overflow: hidden;
      border: 1px solid rgba(120, 130, 240, 0.1);
    }

    .version-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-hover);
    }

    .version-card.current-version {
      background: linear-gradient(135deg, #ffffff 0%, #f8f9ff 100%);
